using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Core.Services.Projects;
namespace RAWSelectionAssistant.Views;
/// <summary>WPF viewing-state host. Shares target/variant identities; not a collage or second library.</summary>
public sealed class StudioViewingTableView:DockPanel
{
 private readonly ReferenceColorWorkspaceViewModel workspace;private readonly Canvas canvas=new(){Width=2400,Height=3600,Background=new SolidColorBrush(Color.FromRgb(28,29,30))};private readonly TextBlock status=new(){TextWrapping=TextWrapping.Wrap,Foreground=Brushes.Gainsboro,Margin=new Thickness(6)};private ViewingFrame? selected;private Point? drag;private FrameworkElement? dragged;private readonly System.Windows.Threading.DispatcherTimer slide=new(){Interval=TimeSpan.FromSeconds(3)};private int slideIndex;private readonly ContentControl detail=new(){Visibility=Visibility.Collapsed,Height=260};private long detailRevision;private CancellationTokenSource? detailCancellation;private bool closed;
 internal Func<ViewingTableItem,int,CancellationToken,Task<BitmapSource>>? DetailRenderer;
 internal Func<CancellationToken,Task>? RefreshLoader;
 internal object? DetailContent=>detail.Content;internal string VisibleStatus=>status.Text;
 internal bool IsClosed=>closed;
 public event Action? ReturnRequested;
 public StudioViewingTableView(ReferenceColorWorkspaceViewModel model)
 {
  workspace=model;Background=new SolidColorBrush(Color.FromRgb(29,29,32));LastChildFill=true;var bar=new WrapPanel();Button Add(string text,Action action){var b=new Button{Content=text,Margin=new Thickness(3),Padding=new Thickness(6,3,6,3)};b.Click+=(_,_)=>action();System.Windows.Automation.AutomationProperties.SetName(b,text);bar.Children.Add(b);return b;}
  Add("固定所选照片/变体",()=>Run(async()=>{workspace.PinSelectedViewingVariants();await RefreshAsync();}));Add("显式重新固定所选",()=>Run(async()=>{workspace.PinSelectedViewingVariants(true);await RefreshAsync();}));Add("移出所选",()=>Run(async()=>{if(selected is not null)workspace.RemoveViewingItem(selected.Item.TargetId,selected.Item.VariantId);await RefreshAsync();}));Add("清空灯箱",()=>Run(async()=>{workspace.ClearViewingPlacements();await RefreshAsync();}));Add("局部放大（代理）",()=>Run(ShowDetailAsync));Add("旋转90°",()=>TransformSelected(1,90));Add("放大",()=>TransformSelected(1.15,0));Add("缩小",()=>TransformSelected(1/1.15,0));Add("比较所选与下一张",()=>Run(CompareAsync));Add("幻灯/停止",()=>{if(slide.IsEnabled)StopSlideshow();else{InvalidateRequests();slide.Start();if(workspace.ViewingFrames.Count>0){selected=workspace.ViewingFrames[0];Run(ShowDetailAsync);}}});Add("创意胶片（8位）",()=>Run(async()=>{if(selected is null)throw new InvalidOperationException("先选择固定照片");await workspace.GenerateViewingFilmAsync(selected.Item);await RefreshAsync();}));var spek=Add("SpektraLab（未准入）",()=>{});spek.IsEnabled=false;spek.ToolTip=FilmBackendRegistryV1.Backends.Single(x=>x.Id=="spektralab").Reason;Add("取消任务",()=>{InvalidateRequests();slide.Stop();workspace.CancelFilmBackendTask();workspace.CancelViewing();});Add("保存项目",()=>Run(async()=>await workspace.SaveSessionCommand.ExecuteAsync(null)));Add("返回暗室",()=>Run(ReturnToDarkroomAsync));var light=new CheckBox{Content="展示灯光（仅观片）",IsChecked=workspace.ViewingTable.PresentationLight,Margin=new Thickness(6)};light.Checked+=(_,_)=>{workspace.SetViewingLight(true);UpdateLight();};light.Unchecked+=(_,_)=>{workspace.SetViewingLight(false);UpdateLight();};bar.Children.Add(light);SetDock(bar,Dock.Top);Children.Add(bar);SetDock(status,Dock.Top);Children.Add(status);SetDock(detail,Dock.Bottom);Children.Add(detail);scroll.Content=canvas;Children.Add(scroll);scroll.ScrollChanged+=(_,e)=>{if(closed||detail.Visibility==Visibility.Visible||e.VerticalChange==0&&e.HorizontalChange==0)return;UpdateCards();viewportWork=RefreshAsync(true);};SizeChanged+=(_,_)=>UpdateCards();
  slide.Tick+=(_,_)=>{if(workspace.ViewingFrames.Count==0)return;selected=workspace.ViewingFrames[slideIndex++%workspace.ViewingFrames.Count];Run(ShowDetailAsync);};Unloaded+=(_,_)=>Close();UpdateLight();
 }
 private void Run(Func<Task> action)=>RunAsync(action);
 private async void RunAsync(Func<Task> action){var before=detailRevision;try{await action();}catch(Exception e)when(e is IOException or InvalidOperationException or NotSupportedException or ArgumentException or OperationCanceledException){if(!closed&&before==detailRevision)status.Text=e is OperationCanceledException?"操作已取消":e.Message;}}
 private void InvalidateRequests(){detailRevision++;var old=detailCancellation;detailCancellation=null;old?.Cancel();workspace.InvalidateViewingRequests();}
 private (long Revision,CancellationTokenSource Cancellation) BeginRequest(){InvalidateRequests();var c=new CancellationTokenSource();detailCancellation=c;return(detailRevision,c);}
 internal void StopSlideshow(){slide.Stop();InvalidateRequests();}
 internal void SelectFrame(ViewingFrame frame)=>selected=frame;
 private void UpdateLight()=>canvas.Background=new SolidColorBrush(workspace.ViewingTable.PresentationLight?Color.FromRgb(65,64,59):Color.FromRgb(28,29,30));
 private readonly ScrollViewer scroll=new(){HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
 private readonly Dictionary<Guid,Border> realized=[];private bool updatingViewport;private Task viewportWork=Task.CompletedTask;
 internal int RealizedCardCount=>realized.Count;internal Task ViewportWork=>viewportWork;
 internal async Task RefreshForViewportAsync(){if(closed)return;await RefreshAsync();}
 private void UpdateCards()
 {
  if(closed||updatingViewport)return;updatingViewport=true;try{
   var width=Math.Max(600,scroll.ViewportWidth);var height=Math.Max(400,scroll.ViewportHeight);var visible=new Rect(scroll.HorizontalOffset-220,scroll.VerticalOffset-160,width+440,height+320);
   var items=workspace.ViewingTable.Items.Where(i=>visible.IntersectsWith(new Rect(i.X-210*Math.Min(i.Scale,8),i.Y-150*Math.Min(i.Scale,8),420*Math.Min(i.Scale,8),300*Math.Min(i.Scale,8)))).Take(32).ToArray();var wanted=items.Select(i=>i.VariantId).ToHashSet();
   foreach(var id in realized.Keys.Where(id=>!wanted.Contains(id)).ToArray()){canvas.Children.Remove(realized[id]);realized[id].Child=null;realized.Remove(id);}
   foreach(var item in items){var frame=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.TargetId==item.TargetId&&f.Item.VariantId==item.VariantId);if(!realized.TryGetValue(item.VariantId,out var card)){card=CreateCard(item);realized[item.VariantId]=card;canvas.Children.Add(card);}UpdateCard(card,item,frame);}
  }finally{updatingViewport=false;}
 }
 private Border CreateCard(ViewingTableItem item)
 {
  var card=new Border{Width=210,Height=150,Background=new SolidColorBrush(Color.FromRgb(37,38,39)),BorderBrush=Brushes.Gray,BorderThickness=new Thickness(1),Padding=new Thickness(5),Tag=item};
  card.MouseLeftButtonDown+=(_,e)=>{var value=(ViewingTableItem)card.Tag;selected=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==value.VariantId);if(selected is null)return;drag=e.GetPosition(canvas);dragged=card;card.CaptureMouse();status.Text=selected.ResolutionLabel+" · 固定版本 "+value.VariantId.ToString("N")[..8];e.Handled=true;};
  card.MouseMove+=(_,e)=>{if(drag is not{} point||dragged!=card||e.LeftButton!=MouseButtonState.Pressed)return;var next=e.GetPosition(canvas);Canvas.SetLeft(card,Math.Clamp(Canvas.GetLeft(card)+next.X-point.X,0,2200));Canvas.SetTop(card,Math.Clamp(Canvas.GetTop(card)+next.Y-point.Y,0,3400));drag=next;};
  card.MouseLeftButtonUp+=(_,_)=>{if(dragged!=card)return;var value=(ViewingTableItem)card.Tag;workspace.SetViewingPlacement(value.TargetId,value.VariantId,Canvas.GetLeft(card),Canvas.GetTop(card),value.Scale,value.Rotation);drag=null;dragged=null;card.ReleaseMouseCapture();UpdateCards();};card.MouseWheel+=(_,e)=>{var value=(ViewingTableItem)card.Tag;selected=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==value.VariantId);TransformSelected(e.Delta>0?1.1:1/1.1,0);e.Handled=true;};return card;
 }
 private void UpdateCard(Border card,ViewingTableItem item,ViewingFrame? frame)
 {
  Canvas.SetLeft(card,item.X);Canvas.SetTop(card,item.Y);card.Tag=item;ApplyTransform(card,item);var failureText=workspace.ViewingFailures.FirstOrDefault(f=>f.StartsWith(ReferenceColorWorkspaceViewModel.ViewingFailurePrefix(item),StringComparison.Ordinal));object displayKey=frame?.Image??(object)(failureText??"pending");if(Equals(card.DataContext,displayKey))return;card.DataContext=displayKey;var key=frame?.Image;var old=(card.Child as DockPanel)?.Children.OfType<Image>().SingleOrDefault()?.Source;if(key is not null&&ReferenceEquals(key,old))return;
  var content=new DockPanel();var label=new TextBlock{Text=item.FrozenVariant.Name+" · "+item.VariantId.ToString("N")[..8],Foreground=Brushes.Gainsboro,TextTrimming=TextTrimming.CharacterEllipsis};SetDock(label,Dock.Bottom);content.Children.Add(label);
  if(frame is not null)content.Children.Add(new Image{Source=frame.Image,Stretch=Stretch.Uniform});else{var failure=workspace.ViewingFailures.FirstOrDefault(f=>f.StartsWith(ReferenceColorWorkspaceViewModel.ViewingFailurePrefix(item),StringComparison.Ordinal));if(failure is not null){var retry=new Button{Content="载入失败 · 重试",ToolTip=failure};retry.Click+=(_,e)=>{e.Handled=true;viewportWork=RetryAsync(item);};content.Children.Add(retry);}else content.Children.Add(new TextBlock{Text="等待代理…",Foreground=Brushes.Gray,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center});}card.Child=content;
 }
 private async Task RetryAsync(ViewingTableItem item){if(closed)return;slide.Stop();var request=BeginRequest();try{await workspace.RetryViewingItemAsync(item,request.Cancellation.Token);if(Current(request)){UpdateCards();status.Text=workspace.ViewingStatus;}}finally{Finish(request);}}
 internal void ScrollForTest(double y)=>scroll.ScrollToVerticalOffset(y);
 public Task RefreshAsync()=>RefreshAsync(false);
 private async Task RefreshAsync(bool visibleOnly)
 {
  if(closed)return;slide.Stop();var request=BeginRequest();detail.Content=null;detail.Visibility=Visibility.Collapsed;UpdateCards();status.Text="准备固定变体代理…";var state=workspace.ViewingTable;var priority=realized.Keys.ToArray();
  System.ComponentModel.PropertyChangedEventHandler changed=(_,e)=>{if(!Current(request))return;if(e.PropertyName is nameof(workspace.ViewingFrames) or nameof(workspace.ViewingFailures)){UpdateCards();status.Text=workspace.ViewingStatus;}};workspace.PropertyChanged+=changed;
  try{await Dispatcher.InvokeAsync(()=>{},System.Windows.Threading.DispatcherPriority.Render);if(!Current(request))return;if(RefreshLoader is{} load)await load(request.Cancellation.Token);else await workspace.PrepareViewingTableAsync(request.Cancellation.Token,priority,visibleOnly);if(!Current(request)||!ReferenceEquals(state,workspace.ViewingTable))return;UpdateCards();selected=workspace.ViewingFrames.FirstOrDefault();status.Text=workspace.ViewingStatus;}
  catch(Exception e)when(e is IOException or InvalidOperationException or NotSupportedException or ArgumentException or OperationCanceledException){if(Current(request))status.Text=e is OperationCanceledException?"操作已取消":e.Message;}
  finally{workspace.PropertyChanged-=changed;Finish(request);}
 }
 private bool Current((long Revision,CancellationTokenSource Cancellation) request)=>!closed&&request.Revision==detailRevision&&!request.Cancellation.IsCancellationRequested;
 private void Finish((long Revision,CancellationTokenSource Cancellation) request){if(ReferenceEquals(detailCancellation,request.Cancellation))detailCancellation=null;request.Cancellation.Dispose();}
 private ViewingTableItem CurrentItem(ViewingTableItem item)=>workspace.ViewingTable.Items.Single(i=>i.TargetId==item.TargetId&&i.VariantId==item.VariantId);
 private static void ApplyTransform(FrameworkElement element,ViewingTableItem item){var transform=new TransformGroup();transform.Children.Add(new ScaleTransform(item.Scale,item.Scale));transform.Children.Add(new RotateTransform(item.Rotation));element.RenderTransform=transform;element.RenderTransformOrigin=new Point(.5,.5);}
 private void TransformSelected(double scale,double rotate){if(selected is null)return;var item=CurrentItem(selected.Item);var next=item with{Scale=Math.Clamp(item.Scale*scale,.1,8),Rotation=(item.Rotation+rotate)%360};workspace.SetViewingPlacement(item.TargetId,item.VariantId,next.X,next.Y,next.Scale,next.Rotation);foreach(var card in canvas.Children.OfType<FrameworkElement>())if(card.Tag is ViewingTableItem frame&&frame.TargetId==item.TargetId&&frame.VariantId==item.VariantId)ApplyTransform(card,next);}
 internal async Task ShowDetailAsync(){if(closed||selected is null)return;var request=BeginRequest();var frame=selected;try{var image=await (DetailRenderer??workspace.RenderViewingItemAsync)(frame.Item,1600,request.Cancellation.Token);if(!Current(request))return;var viewport=new ColorStudioImageViewport{Original=image,Mode="原片",SourcePixelSize=new Size(image.PixelWidth,image.PixelHeight)};viewport.MouseWheel+=(_,e)=>{viewport.State.ZoomAbout(e.GetPosition(viewport),e.Delta>0?1.2:1/1.2);e.Handled=true;};Point? detailPan=null;viewport.MouseLeftButtonDown+=(_,e)=>{if(e.ClickCount==2){viewport.State.Fit();e.Handled=true;return;}detailPan=e.GetPosition(viewport);viewport.CaptureMouse();e.Handled=true;};viewport.MouseMove+=(_,e)=>{if(detailPan is{} start&&e.LeftButton==MouseButtonState.Pressed){var next=e.GetPosition(viewport);viewport.State.PanBy(next-start);detailPan=next;}};viewport.MouseLeftButtonUp+=(_,_)=>{detailPan=null;viewport.ReleaseMouseCapture();};viewport.LostMouseCapture+=(_,_)=>detailPan=null;var root=new DockPanel();var label=new TextBlock{Text=$"局部放大：实际代理 {image.PixelWidth}×{image.PixelHeight}；不是原图1:1细节",Foreground=Brushes.Gainsboro};SetDock(label,Dock.Top);root.Children.Add(label);root.Children.Add(viewport);detail.Content=root;detail.Visibility=Visibility.Visible;}catch(Exception e)when(e is IOException or InvalidOperationException or NotSupportedException or ArgumentException or OperationCanceledException){if(Current(request))status.Text=e is OperationCanceledException?"操作已取消":e.Message;}finally{Finish(request);}}
 internal Task CompareAsync(){if(closed)return Task.CompletedTask;var frames=workspace.ViewingFrames;slide.Stop();InvalidateRequests();if(selected is null||frames.Count<2)return Task.CompletedTask;var index=frames.ToList().IndexOf(selected);var other=frames[(index+1)%frames.Count];var compare=new StudioSharedComparisonView();compare.SetFrames(new[]{selected,other}.Select(f=>new R53VariantFrame(f.Item.VariantId,f.Item.FrozenVariant.Name,f.Image){SourceTargetId=f.Item.TargetId,SourceVersionId=f.Item.VariantId,SourceHash=f.Item.SourceHash}).ToArray());detail.Content=compare;detail.Visibility=Visibility.Visible;return Task.CompletedTask;}
 private async Task ReturnToDarkroomAsync(){if(closed)return;slide.Stop();var request=BeginRequest();var frame=selected;try{if(frame is not null)await workspace.ReturnViewingToDarkroomAsync(frame.Item,request.Cancellation.Token);if(!Current(request))return;Close();ReturnRequested?.Invoke();}finally{Finish(request);}}
 public void Close(){if(closed)return;closed=true;slide.Stop();InvalidateRequests();workspace.CancelFilmBackendTask();workspace.ReleaseViewing();dragged?.ReleaseMouseCapture();dragged=null;drag=null;selected=null;canvas.Children.Clear();realized.Clear();detail.Content=null;}
}
